ALTER TABLE public.fornecedores ADD COLUMN nome_fantasia text, ADD COLUMN endereco text, ADD COLUMN cidade text, ADD COLUMN uf text, ADD COLUMN contatos text, ADD COLUMN ativo boolean NOT NULL DEFAULT true;
ALTER TABLE public.comprovantes ADD COLUMN tipo_documento text NOT NULL DEFAULT 'canhoto', ADD COLUMN triagem text NOT NULL DEFAULT 'pendente' CHECK(triagem IN ('pendente','analisado','nova_foto')), ADD COLUMN observacoes_documento text NOT NULL DEFAULT '';
CREATE TABLE public.documento_vinculos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),comprovante_id uuid NOT NULL REFERENCES public.comprovantes(id),nota_id uuid REFERENCES public.notas_fiscais(id),carga_id uuid REFERENCES public.cargas(id),entrega_id uuid REFERENCES public.entregas(id),UNIQUE(comprovante_id,nota_id,carga_id,entrega_id),CHECK(nota_id IS NOT NULL OR carga_id IS NOT NULL OR entrega_id IS NOT NULL));
GRANT SELECT,INSERT,UPDATE ON public.documento_vinculos TO authenticated; GRANT ALL ON public.documento_vinculos TO service_role; ALTER TABLE public.documento_vinculos ENABLE ROW LEVEL SECURITY; CREATE POLICY office_document_links ON public.documento_vinculos FOR ALL TO authenticated USING(private.can_write(auth.uid())) WITH CHECK(private.can_write(auth.uid()));
CREATE TABLE public.distancias(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),cidade text NOT NULL,uf text NOT NULL,ibge text,km numeric NOT NULL CHECK(km>=0),fonte text NOT NULL,atualizado_em timestamptz NOT NULL DEFAULT now(),UNIQUE(cidade,uf));
GRANT SELECT,INSERT,UPDATE ON public.distancias TO authenticated; GRANT ALL ON public.distancias TO service_role; ALTER TABLE public.distancias ENABLE ROW LEVEL SECURITY; CREATE POLICY finance_distances ON public.distancias FOR ALL TO authenticated USING(private.can_finance(auth.uid())) WITH CHECK(private.can_finance(auth.uid()));
CREATE TABLE public.tabelas_frete(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),fornecedor_id uuid NOT NULL REFERENCES public.fornecedores(id),nome text NOT NULL,inicio date NOT NULL,fim date,ativo boolean NOT NULL DEFAULT false,versao integer NOT NULL DEFAULT 1,regras jsonb NOT NULL,criado_por uuid DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),CHECK(fim IS NULL OR fim>=inicio));
GRANT SELECT,INSERT ON public.tabelas_frete TO authenticated; GRANT ALL ON public.tabelas_frete TO service_role; ALTER TABLE public.tabelas_frete ENABLE ROW LEVEL SECURITY; CREATE POLICY freight_tables_read ON public.tabelas_frete FOR SELECT TO authenticated USING(private.can_finance(auth.uid())); CREATE POLICY freight_tables_write ON public.tabelas_frete FOR INSERT TO authenticated WITH CHECK(private.can_finance(auth.uid()));
CREATE TABLE public.calculos_frete(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),nota_id uuid NOT NULL REFERENCES public.notas_fiscais(id),tabela_id uuid REFERENCES public.tabelas_frete(id),situacao text NOT NULL,total numeric,memoria jsonb NOT NULL DEFAULT '{}',motivo text NOT NULL DEFAULT '',criado_por uuid DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.calculos_frete TO authenticated; GRANT ALL ON public.calculos_frete TO service_role; ALTER TABLE public.calculos_frete ENABLE ROW LEVEL SECURITY; CREATE POLICY freight_calcs_read ON public.calculos_frete FOR SELECT TO authenticated USING(private.can_finance(auth.uid()));
ALTER TABLE public.financeiro ADD COLUMN calculo_id uuid REFERENCES public.calculos_frete(id), ADD COLUMN comprovante_id uuid REFERENCES public.comprovantes(id), ADD COLUMN entrega_id uuid REFERENCES public.entregas(id), ADD COLUMN estado_frete text NOT NULL DEFAULT 'calculo_pendente', ADD COLUMN distancia numeric, ADD COLUMN valor_ad_valorem numeric NOT NULL DEFAULT 0, ADD COLUMN valor_tributos numeric NOT NULL DEFAULT 0, ADD COLUMN ajuste numeric NOT NULL DEFAULT 0;
CREATE OR REPLACE FUNCTION public.tg_freight_version() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b jsonb; prev numeric:=-1; r jsonb; BEGIN IF NOT private.can_finance(auth.uid()) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF; IF NEW.regras->>'metodo' NOT IN ('kg','tonelada','percentual','fixo','faixas') OR coalesce(NEW.regras->>'metodo','')='' THEN RAISE EXCEPTION 'Método inválido'; END IF; IF coalesce((NEW.regras->>'tarifa')::numeric,0)<0 OR coalesce((NEW.regras->>'minimo')::numeric,0)<0 THEN RAISE EXCEPTION 'Valor inválido'; END IF; IF NEW.regras->>'metodo'='faixas' THEN IF jsonb_array_length(coalesce(NEW.regras->'faixas','[]'))=0 THEN RAISE EXCEPTION 'Cadastre as faixas'; END IF; FOR b IN SELECT value FROM jsonb_array_elements(NEW.regras->'faixas') ORDER BY (value->>'inicio')::numeric LOOP IF (b->>'inicio')::numeric<0 OR (b->>'fim')::numeric<=(b->>'inicio')::numeric OR (b->>'tarifa')::numeric<0 THEN RAISE EXCEPTION 'Faixa inválida'; END IF; IF prev=-1 AND (b->>'inicio')::numeric<>0 OR prev<>-1 AND (b->>'inicio')::numeric<>prev THEN RAISE EXCEPTION 'Faixas sobrepostas ou com intervalo não coberto'; END IF; IF b->>'unidade' NOT IN ('kg','tonelada','fixo') THEN RAISE EXCEPTION 'Unidade inválida'; END IF; prev:=(b->>'fim')::numeric; END LOOP; END IF; FOR r IN SELECT value FROM jsonb_array_elements(coalesce(NEW.regras->'operacoes','[]')) LOOP IF r->>'tipo' NOT IN ('percentual','fixo','minimo','icms','iss') OR r->>'base' NOT IN ('nf','frete','acumulado','contratual') OR (r->>'valor')::numeric<0 THEN RAISE EXCEPTION 'Operação inválida'; END IF; IF r->>'tipo' IN ('icms','iss') AND (r->>'valor')::numeric>=100 THEN RAISE EXCEPTION 'Tributo inválido'; END IF; END LOOP; IF EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(NEW.regras->'operacoes','[]')) x WHERE x->>'tipo'='icms') AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(NEW.regras->'operacoes','[]')) x WHERE x->>'tipo'='iss') THEN RAISE EXCEPTION 'Configure ICMS ou ISS, não ambos'; END IF; PERFORM 1 FROM fornecedores WHERE id=NEW.fornecedor_id FOR UPDATE; SELECT coalesce(max(versao),0)+1 INTO NEW.versao FROM tabelas_frete WHERE fornecedor_id=NEW.fornecedor_id AND nome=NEW.nome; NEW.criado_por:=auth.uid(); RETURN NEW; END $$;
CREATE TRIGGER freight_version BEFORE INSERT ON tabelas_frete FOR EACH ROW EXECUTE FUNCTION public.tg_freight_version();
CREATE OR REPLACE FUNCTION public.simular_frete(_regras jsonb,_peso numeric,_valor numeric,_km numeric DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE metodo text:=_regras->>'metodo'; tarifa numeric:=coalesce((_regras->>'tarifa')::numeric,0); base numeric:=0; total numeric:=0; v numeric; bc numeric; trib numeric:=0; adv numeric:=0; extras numeric:=0; b jsonb; op jsonb; passos jsonb:='[]'; unidade text; BEGIN IF _peso<0 OR _valor<0 THEN RAISE EXCEPTION 'Peso ou valor inválido'; END IF; IF metodo='faixas' THEN IF _km IS NULL THEN RETURN jsonb_build_object('situacao','aguardando_distancia','total',NULL); END IF; SELECT value INTO b FROM jsonb_array_elements(_regras->'faixas') WHERE _km<=(value->>'fim')::numeric AND (_km>(value->>'inicio')::numeric OR (_km=0 AND (value->>'inicio')::numeric=0)) ORDER BY (value->>'inicio')::numeric LIMIT 1; IF b IS NULL THEN RETURN jsonb_build_object('situacao','calculo_pendente','erro','Distância fora das faixas','total',NULL); END IF; tarifa:=(b->>'tarifa')::numeric; unidade:=b->>'unidade'; ELSE unidade:=metodo; END IF; base:=CASE unidade WHEN 'kg' THEN _peso*tarifa WHEN 'tonelada' THEN _peso/1000*tarifa WHEN 'percentual' THEN CASE WHEN _regras->>'base_percentual'='contratual' THEN coalesce((_regras->>'base_contratual')::numeric,0) ELSE _valor END *tarifa/100 WHEN 'fixo' THEN tarifa ELSE NULL END; IF base IS NULL THEN RETURN jsonb_build_object('situacao','calculo_pendente','total',NULL); END IF; total:=base; FOR op IN SELECT value FROM jsonb_array_elements(coalesce(_regras->'operacoes','[]')) LOOP bc:=CASE op->>'base' WHEN 'nf' THEN _valor WHEN 'frete' THEN base WHEN 'contratual' THEN coalesce((_regras->>'base_contratual')::numeric,0) ELSE total END; IF op->>'uf' IS NOT NULL OR op->>'cidade' IS NOT NULL THEN CONTINUE; END IF; v:=(op->>'valor')::numeric; IF op->>'tipo'='minimo' THEN v:=greatest(v-total,0); ELSIF op->>'tipo'<>'fixo' THEN IF op->>'por_dentro'='true' THEN IF v>=100 THEN RAISE EXCEPTION 'Percentual inválido'; END IF; v:=bc/(1-v/100)-bc; ELSE v:=bc*v/100; END IF; END IF; total:=total+v; IF op->>'tipo' IN ('icms','iss') THEN trib:=trib+v; ELSIF op->>'tipo'='percentual' THEN adv:=adv+v; ELSE extras:=extras+v; END IF; passos:=passos||jsonb_build_array(jsonb_build_object('nome',op->>'nome','tipo',op->>'tipo','base',bc,'valor',round(v,2))); END LOOP; total:=greatest(total,coalesce((_regras->>'minimo')::numeric,0)); RETURN jsonb_build_object('situacao','pre_calculado','peso',_peso,'valor_nf',_valor,'distancia',_km,'faixa',b,'tarifa',tarifa,'base',round(base,2),'ad_valorem',round(adv,2),'adicionais',round(extras,2),'tributos',round(trib,2),'passos',passos,'total',round(total,2)); END $$;
REVOKE ALL ON FUNCTION public.simular_frete(jsonb,numeric,numeric,numeric) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.simular_frete(jsonb,numeric,numeric,numeric) TO authenticated,service_role;
